import { useCallback, useEffect, useState } from 'react';
import { clsx } from 'clsx';
import { LayoutDashboard, ListOrdered, Plus, RotateCcw, Target } from 'lucide-react';
import type { LucideIcon } from 'lucide-react';
import './index.css';
import { catById } from './data/categories';
import { IMG } from './data/images';
import { OWNER } from './data/seed';
import type { Tx } from './data/seed';
import { currentMonth, monthKey, moneyRound } from './lib/format';
import { monthTotals, useFinance } from './lib/store';
import Overview from './components/Overview';
import Transactions from './components/Transactions';
import Budgets from './components/Budgets';
import TxForm from './components/TxForm';
import { Button, Modal, MonthStepper, Toast } from './components/ui';
import type { ToastMsg } from './components/ui';

type View = 'resumen' | 'movimientos' | 'presupuestos';
const NAV: { id: View; label: string; icon: LucideIcon; title: string }[] = [
  { id: 'resumen', label: 'Resumen', icon: LayoutDashboard, title: 'Tu mes de un vistazo' },
  { id: 'movimientos', label: 'Movimientos', icon: ListOrdered, title: 'Movimientos' },
  { id: 'presupuestos', label: 'Presupuestos', icon: Target, title: 'Presupuestos mensuales' },
];

const readHash = (): View => {
  const h = window.location.hash.replace('#/', '');
  return (NAV.some(n => n.id === h) ? h : 'resumen') as View;
};

export default function App() {
  const fin = useFinance();
  const [view, setView] = useState<View>(readHash);
  const [month, setMonth] = useState(currentMonth());
  const [editing, setEditing] = useState<Tx | 'new' | null>(null);
  const [confirmReset, setConfirmReset] = useState(false);
  const [toast, setToast] = useState<ToastMsg | null>(null);

  useEffect(() => {
    const onHash = () => setView(readHash());
    window.addEventListener('hashchange', onHash);
    return () => window.removeEventListener('hashchange', onHash);
  }, []);

  const go = (v: View) => {
    setView(v);
    setEditing(null);
    try { if (window.location.hash !== `#/${v}`) window.history.replaceState(null, '', `#/${v}`); } catch { /* vista previa sin URL */ }
    window.scrollTo({ top: 0 });
  };
  const notify = (text: string, action?: ToastMsg['action']) => setToast({ id: Date.now(), text, action });
  const closeToast = useCallback(() => setToast(null), []);

  const onSave = (tx: Omit<Tx, 'id'> & { id?: string }) => {
    if (tx.id) fin.updateTx(tx as Tx); else fin.addTx(tx);
    setEditing(null);
    const limit = fin.data.budgets[tx.categoryId];
    if (tx.type === 'gasto' && limit) {
      const others = fin.data.txs.filter(t => t.id !== tx.id);
      const spent = monthTotals(others, monthKey(tx.date)).byCat[tx.categoryId] ?? 0;
      if (spent + tx.amount > limit) {
        notify(`Te has pasado en ${catById(tx.categoryId).name}: ${moneyRound(spent + tx.amount)} de ${moneyRound(limit)}`);
        return;
      }
    }
    notify(tx.id ? 'Cambios guardados' : tx.type === 'gasto' ? 'Gasto añadido' : 'Ingreso añadido');
  };
  const onDelete = (tx: Tx) => {
    fin.deleteTx(tx.id);
    setEditing(null);
    notify(`Borrado «${tx.concept}»`, { label: 'Deshacer', run: () => fin.restoreTx(tx) });
  };

  const current = NAV.find(n => n.id === view)!;

  return (
    <div className="cc-app min-h-screen bg-[#F5F2F8] text-[#2A1E3F]">
      {/* Barra lateral (escritorio) */}
      <aside className="fixed inset-y-0 left-0 z-20 hidden w-[248px] flex-col border-r border-[#E7E0EF] bg-[#FBFAFD] px-4 py-6 lg:flex">
        <Brand />
        <nav className="mt-9 space-y-1" aria-label="Secciones">
          {NAV.map(n => (
            <button
              key={n.id} onClick={() => go(n.id)} aria-current={view === n.id ? 'page' : undefined}
              className={clsx('flex h-11 w-full items-center gap-3 rounded-2xl px-3.5 text-[15px] font-semibold transition-colors',
                view === n.id ? 'bg-[#2A1E3F] text-white' : 'text-[#5E5470] hover:bg-[#F0EAF6] hover:text-[#2A1E3F]')}
            >
              <n.icon size={19} strokeWidth={2} />{n.label}
            </button>
          ))}
        </nav>
        <div className="mt-auto rounded-[20px] bg-[#FFF4E2] p-4">
          <p className="cc-display text-[16px] font-semibold text-[#2A1E3F]">Consejo del mes</p>
          <p className="mt-1 text-[13px] leading-relaxed text-[#5C4A2E]">Apunta los gastos pequeños el mismo día: son los que más se escapan del presupuesto.</p>
        </div>
        <div className="mt-4 flex items-center gap-3 px-1">
          <img src={IMG(OWNER.photo)} alt={`Foto de ${OWNER.fullName}`} className="h-9 w-9 rounded-full bg-[#E2D8EF] object-cover" />
          <div className="min-w-0 flex-1">
            <p className="truncate text-[14px] font-semibold">{OWNER.fullName}</p>
            <button onClick={() => setConfirmReset(true)} className="flex items-center gap-1 rounded text-[12px] text-[#6B6178] hover:text-[#2A1E3F]">
              <RotateCcw size={12} />Restablecer datos
            </button>
          </div>
        </div>
      </aside>

      <div className="lg:pl-[248px]">
        {/* Cabecera */}
        <header className="sticky top-0 z-10 border-b border-[#E7E0EF] bg-[#F5F2F8]/90 backdrop-blur">
          <div className="mx-auto flex max-w-[1180px] items-center gap-3 px-4 py-3 sm:px-6 lg:px-8 lg:py-4">
            <div className="lg:hidden"><Brand compact /></div>
            <h1 className="cc-display hidden text-[26px] font-semibold lg:block">{current.title}</h1>
            <div className="ml-auto flex items-center gap-2">
              <MonthStepper month={month} onChange={setMonth} className="hidden sm:inline-flex" />
              <Button onClick={() => setEditing('new')} className="!bg-[#F2A93B] !text-[#2A1E3F] hover:!bg-[#F5B957]" aria-label="Añadir movimiento">
                <Plus size={18} strokeWidth={2.5} /><span className="hidden sm:inline">Añadir movimiento</span>
              </Button>
            </div>
          </div>
          {/* Pestañas (móvil y tableta) */}
          <nav className="grid grid-cols-3 gap-1.5 px-4 pb-3 sm:flex sm:px-6 lg:hidden" aria-label="Secciones">
            {NAV.map(n => (
              <button
                key={n.id} onClick={() => go(n.id)} aria-current={view === n.id ? 'page' : undefined}
                className={clsx('flex h-10 items-center justify-center gap-2 rounded-full px-2 text-[14px] sm:px-4 font-semibold transition-colors',
                  view === n.id ? 'bg-[#2A1E3F] text-white' : 'bg-white text-[#5E5470] ring-1 ring-[#E7E0EF]')}
              >
                <n.icon size={16} className="hidden sm:block" />{n.label}
              </button>
            ))}
          </nav>
        </header>

        <main className="mx-auto max-w-[1180px] px-4 pb-24 pt-5 sm:px-6 lg:px-8 lg:pt-7">
          <div className="mb-4 flex justify-center sm:hidden">
            <MonthStepper month={month} onChange={setMonth} />
          </div>
          <div key={view} className="cc-fade">
            {view === 'resumen' && <Overview fin={fin} month={month} setMonth={setMonth} onOpen={setEditing} go={go} />}
            {view === 'movimientos' && <Transactions fin={fin} month={month} onOpen={setEditing} onNew={() => setEditing('new')} notify={notify} />}
            {view === 'presupuestos' && <Budgets fin={fin} month={month} notify={notify} />}
          </div>
          <button onClick={() => setConfirmReset(true)} className="mt-8 flex items-center gap-1.5 rounded text-[13px] text-[#6B6178] hover:text-[#2A1E3F] lg:hidden">
            <RotateCcw size={13} />Restablecer datos de ejemplo
          </button>
        </main>
      </div>

      {editing && (
        <TxForm
          tx={editing === 'new' ? null : editing} accounts={fin.data.accounts} defaultMonth={month}
          onClose={() => setEditing(null)} onSave={onSave} onDelete={onDelete}
        />
      )}
      {confirmReset && (
        <Modal
          title="¿Restablecer los datos?" onClose={() => setConfirmReset(false)}
          footer={<>
            <Button variant="ghost" onClick={() => setConfirmReset(false)}>Cancelar</Button>
            <Button variant="danger" className="ml-auto" onClick={() => { fin.reset(); setConfirmReset(false); setMonth(currentMonth()); notify('Datos de ejemplo restablecidos'); }}>Sí, restablecer</Button>
          </>}
        >
          <p className="text-[15px] leading-relaxed text-[#5E5470]">Se borrarán tus movimientos y presupuestos y volverán los datos de ejemplo de {OWNER.name}. No se puede deshacer.</p>
        </Modal>
      )}
      <Toast toast={toast} onDone={closeToast} />
    </div>
  );
}

function Brand({ compact }: { compact?: boolean }) {
  return (
    <div className="flex items-center gap-2.5 px-1">
      <svg width="34" height="34" viewBox="0 0 34 34" aria-hidden="true">
        <rect width="34" height="34" rx="11" fill="#2A1E3F" />
        <circle cx="17" cy="17" r="9" fill="none" stroke="#8B6FCB" strokeWidth="2" />
        <circle cx="17" cy="17" r="4.5" fill="#F2A93B" />
      </svg>
      <span className={clsx('cc-display font-semibold leading-none', compact ? 'text-[19px]' : 'text-[21px]')}>Cuentas Claras</span>
    </div>
  );
}

import { useMemo, useState } from 'react';
import { clsx } from 'clsx';
import { AlertTriangle, CheckCircle2, Pencil } from 'lucide-react';
import { catById, categoriesOf } from '../data/categories';
import { addMonths, currentMonth, monthLabel, moneyRound, parseAmount, pct } from '../lib/format';
import { monthTotals } from '../lib/store';
import type { Finance } from '../lib/store';
import { Button, Card, CatIcon, Progress } from './ui';

type Props = { fin: Finance; month: string; notify: (t: string) => void };

export default function Budgets({ fin, month, notify }: Props) {
  const { data, setBudget } = fin;
  const [editing, setEditing] = useState<string | null>(null);
  const t = useMemo(() => monthTotals(data.txs, month), [data.txs, month]);

  /** Media de gasto de los 3 meses anteriores, para sugerir un límite */
  const avg = (id: string) => {
    const vals = [1, 2, 3].map(i => monthTotals(data.txs, addMonths(month, -i)).byCat[id] ?? 0);
    return vals.reduce((a, b) => a + b, 0) / 3;
  };

  const rows = Object.entries(data.budgets)
    .map(([id, limit]) => ({ id, limit, spent: t.byCat[id] ?? 0 }))
    .sort((a, b) => b.spent / b.limit - a.spent / a.limit);
  const without = categoriesOf('gasto').filter(c => !(c.id in data.budgets));
  const totalLimit = rows.reduce((s, r) => s + r.limit, 0);
  const totalSpent = rows.reduce((s, r) => s + r.spent, 0);
  const over = rows.filter(r => r.spent > r.limit);

  const isCurrent = month === currentMonth();
  const now = new Date();
  const dim = new Date(now.getFullYear(), now.getMonth() + 1, 0).getDate();
  const daysLeft = isCurrent ? dim - now.getDate() + 1 : 0;
  const left = totalLimit - totalSpent;

  const save = (id: string, value: number | null) => {
    setBudget(id, value);
    setEditing(null);
    notify(value === null ? `Presupuesto de ${catById(id).name} eliminado` : `Presupuesto de ${catById(id).name}: ${moneyRound(value)} al mes`);
  };

  return (
    <div className="grid grid-cols-1 gap-5 lg:grid-cols-12">
      <section className="rounded-[26px] bg-[#2A1E3F] p-6 text-white sm:p-7 lg:col-span-12">
        <div className="flex flex-col gap-6 md:flex-row md:items-end">
          <div className="flex-1">
            <p className="text-sm text-white/70">Gastado en {monthLabel(month).toLowerCase()} de lo presupuestado</p>
            <p className="cc-display cc-num mt-1 text-[38px] font-semibold leading-none sm:text-[44px]">
              {moneyRound(totalSpent)} <span className="text-[22px] text-white/60 sm:text-[26px]">de {moneyRound(totalLimit)}</span>
            </p>
            <div className="mt-5 h-3 overflow-hidden rounded-full bg-white/15">
              <div className="cc-fill h-full rounded-full" style={{ width: `${Math.min(100, (totalSpent / Math.max(totalLimit, 1)) * 100)}%`, background: left < 0 ? '#F4A394' : '#F2A93B' }} />
            </div>
          </div>
          <div className="grid grid-cols-2 gap-3 md:w-[360px]">
            <Pill label={left >= 0 ? 'Te queda' : 'Te has pasado'} value={moneyRound(Math.abs(left))} />
            <Pill label={isCurrent ? `Al día (${daysLeft} días)` : 'Categorías pasadas'} value={isCurrent ? moneyRound(Math.max(0, left) / Math.max(daysLeft, 1)) : String(over.length)} />
          </div>
        </div>
      </section>

      {over.length > 0 && (
        <div className="flex items-start gap-3 rounded-[20px] border border-[#F2C9C3] bg-[#FDF0EE] p-4 text-[14px] text-[#7E2A23] lg:col-span-12" role="status">
          <AlertTriangle size={20} className="mt-0.5 shrink-0 text-[#C2453C]" />
          <p><b>Te has pasado en {over.map(o => catById(o.id).name).join(', ')}.</b> Revisa esos gastos o ajusta el límite si el mes ha sido especial.</p>
        </div>
      )}

      <div className="grid gap-4 sm:grid-cols-2 lg:col-span-8">
        {rows.length === 0 && (
          <Card className="p-6 text-[15px] text-[#6B6178] sm:col-span-2">Aún no tienes presupuestos. Crea uno desde la lista de la derecha para recibir avisos cuando te acerques al límite.</Card>
        )}
        {rows.map(r => {
          const c = catById(r.id);
          const ratio = r.spent / r.limit;
          const isOver = ratio > 1;
          return (
            <Card key={r.id} className={clsx('p-5', isOver && 'border-[#F2C9C3]')}>
              <div className="flex items-center gap-3">
                <CatIcon id={r.id} />
                <div className="min-w-0 flex-1">
                  <p className="truncate text-[15px] font-semibold">{c.name}</p>
                  <p className="text-[13px] text-[#6B6178]">Límite {moneyRound(r.limit)} al mes</p>
                </div>
                {editing !== r.id && (
                  <button onClick={() => setEditing(r.id)} className="grid h-9 w-9 place-items-center rounded-full text-[#5E5470] hover:bg-[#F1ECF7]" aria-label={`Editar presupuesto de ${c.name}`}>
                    <Pencil size={16} />
                  </button>
                )}
              </div>
              {editing === r.id ? (
                <LimitEditor initial={r.limit} suggestion={avg(r.id)} onCancel={() => setEditing(null)} onSave={v => save(r.id, v)} onRemove={() => save(r.id, null)} />
              ) : (
                <>
                  <div className="mb-2 mt-4 flex items-baseline justify-between">
                    <span className={clsx('cc-display cc-num text-[22px] font-semibold', isOver ? 'text-[#A8352D]' : 'text-[#2A1E3F]')}>{moneyRound(r.spent)}</span>
                    <span className="cc-num text-[13px] font-semibold text-[#6B6178]">{pct(ratio)}</span>
                  </div>
                  <Progress value={ratio} color={c.color} over={isOver} />
                  <p className={clsx('mt-2.5 flex items-center gap-1.5 text-[13px] font-medium', isOver ? 'text-[#A8352D]' : ratio > 0.85 ? 'text-[#8A5A12]' : 'text-[#24694F]')}>
                    {isOver ? <AlertTriangle size={14} /> : <CheckCircle2 size={14} />}
                    {isOver ? `Te has pasado ${moneyRound(r.spent - r.limit)}` : ratio > 0.85 ? `Cerca del límite: quedan ${moneyRound(r.limit - r.spent)}` : `Quedan ${moneyRound(r.limit - r.spent)}`}
                  </p>
                </>
              )}
            </Card>
          );
        })}
      </div>

      <Card className="self-start p-5 sm:p-6 lg:col-span-4">
        <h2 className="cc-display text-[19px] font-semibold">Sin presupuesto</h2>
        <p className="mt-0.5 text-sm text-[#6B6178]">Te sugerimos un límite según tu media de los últimos 3 meses.</p>
        {without.length === 0 && <p className="mt-4 text-[14px] text-[#6B6178]">Todas tus categorías de gasto tienen presupuesto.</p>}
        <ul className="mt-4 space-y-2">
          {without.map(c => {
            const suggestion = Math.max(20, Math.ceil(avg(c.id) / 10) * 10);
            return (
              <li key={c.id} className="rounded-2xl bg-[#F8F5FB] p-3">
                {editing === c.id ? (
                  <>
                    <p className="text-[14px] font-semibold">{c.name}</p>
                    <LimitEditor initial={suggestion} suggestion={avg(c.id)} onCancel={() => setEditing(null)} onSave={v => save(c.id, v)} />
                  </>
                ) : (
                  <div className="flex items-center gap-3">
                    <CatIcon id={c.id} size={34} />
                    <div className="min-w-0 flex-1">
                      <p className="text-[14px] font-semibold leading-tight">{c.name}</p>
                      <p className="cc-num mt-0.5 text-[12px] text-[#6B6178]">Este mes {moneyRound(t.byCat[c.id] ?? 0)}</p>
                    </div>
                    <Button variant="soft" size="sm" onClick={() => setEditing(c.id)} aria-label={`Crear presupuesto de ${c.name}`}>Crear</Button>
                  </div>
                )}
              </li>
            );
          })}
        </ul>
      </Card>
    </div>
  );
}

function Pill({ label, value }: { label: string; value: string }) {
  return (
    <div className="rounded-2xl bg-white/10 px-4 py-3">
      <p className="truncate text-[13px] text-white/70">{label}</p>
      <p className="cc-num mt-0.5 text-[20px] font-semibold">{value}</p>
    </div>
  );
}

function LimitEditor({ initial, suggestion, onSave, onCancel, onRemove }: {
  initial: number; suggestion: number; onSave: (v: number) => void; onCancel: () => void; onRemove?: () => void;
}) {
  const [value, setValue] = useState(String(initial));
  const [error, setError] = useState('');
  const submit = () => {
    const n = parseAmount(value);
    if (!Number.isFinite(n) || n <= 0) return setError('Escribe un límite mayor que 0.');
    if (n > 100000) return setError('Ese límite parece demasiado alto.');
    onSave(Math.round(n));
  };
  return (
    <form className="cc-fade mt-3" onSubmit={e => { e.preventDefault(); submit(); }}>
      <div className="relative">
        <input className="cc-input cc-num pr-16" inputMode="decimal" value={value} onChange={e => { setValue(e.target.value); setError(''); }} aria-label="Límite mensual" aria-invalid={!!error} autoFocus />
        <span className="pointer-events-none absolute right-3 top-1/2 -translate-y-1/2 text-[14px] text-[#8A7F98]">€/mes</span>
      </div>
      {error ? <p className="mt-1.5 text-[13px] font-medium text-[#A8352D]">{error}</p>
        : <p className="mt-1.5 text-[12px] text-[#6B6178]">Tu media: {moneyRound(suggestion)} al mes</p>}
      <div className="mt-3 flex flex-wrap gap-2">
        <Button size="sm" type="submit">Guardar límite</Button>
        <Button size="sm" variant="ghost" onClick={onCancel}>Cancelar</Button>
        {onRemove && <Button size="sm" variant="danger" className="ml-auto" onClick={onRemove}>Quitar</Button>}
      </div>
    </form>
  );
}

import { useMemo, useState } from 'react';
import { clsx } from 'clsx';
import { AlertTriangle, ArrowDownLeft, ArrowUpRight, ChevronRight, PiggyBank } from 'lucide-react';
import { catById } from '../data/categories';
import { IMG } from '../data/images';
import { OWNER } from '../data/seed';
import type { Tx } from '../data/seed';
import { addMonths, money, monthLabel, monthShort, moneyRound, pct } from '../lib/format';
import { monthTotals } from '../lib/store';
import type { Finance } from '../lib/store';
import { Donut, MonthlyBars } from './charts';
import type { Slice } from './charts';
import { TxRow } from './TxRow';
import { Card, CardTitle, Progress } from './ui';

type Props = { fin: Finance; month: string; setMonth: (m: string) => void; onOpen: (tx: Tx) => void; go: (v: 'movimientos' | 'presupuestos') => void };

export default function Overview({ fin, month, setMonth, onOpen, go }: Props) {
  const { data, balances } = fin;
  const [activeSlice, setActiveSlice] = useState<string | null>(null);
  const total = Object.values(balances).reduce((a, b) => a + b, 0);
  const t = useMemo(() => monthTotals(data.txs, month), [data.txs, month]);
  const saved = t.income - t.expense;

  const slices: Slice[] = useMemo(() => {
    const all = Object.entries(t.byCat).sort((a, b) => b[1] - a[1]);
    const top = all.slice(0, 5).map(([id, value]) => ({ id, value, label: catById(id).name, color: catById(id).color }));
    const rest = all.slice(5).reduce((s, [, v]) => s + v, 0);
    return rest > 0 ? [...top, { id: 'resto', label: 'Otras', value: rest, color: '#B9AFC6' }] : top;
  }, [t.byCat]);

  const bars = useMemo(() => Array.from({ length: 6 }, (_, i) => {
    const key = addMonths(month, i - 5);
    const mt = monthTotals(data.txs, key);
    return { key, label: monthShort(key), income: mt.income, expense: mt.expense };
  }), [data.txs, month]);

  const budgets = Object.entries(data.budgets)
    .map(([id, limit]) => ({ id, limit, spent: t.byCat[id] ?? 0 }))
    .sort((a, b) => b.spent / b.limit - a.spent / a.limit)
    .slice(0, 4);
  const overCount = Object.entries(data.budgets).filter(([id, l]) => (t.byCat[id] ?? 0) > l).length;
  const recent = data.txs.slice(0, 6);
  const accName = (id: string) => data.accounts.find(a => a.id === id)?.name ?? '';

  return (
    <div className="grid grid-cols-1 gap-5 lg:grid-cols-12">
      {/* Saldo total */}
      <section className="relative overflow-hidden rounded-[26px] bg-[#2A1E3F] p-6 text-white sm:p-7 lg:col-span-7">
        <svg className="pointer-events-none absolute -right-16 -top-20 h-[340px] w-[340px] text-[#8B6FCB]" viewBox="0 0 200 200" fill="none" aria-hidden="true">
          {[90, 70, 50, 30].map((r, i) => <circle key={r} cx="100" cy="100" r={r} stroke="currentColor" strokeOpacity={0.12 + i * 0.05} strokeWidth="1.5" />)}
          <circle cx="100" cy="100" r="14" fill="#F2A93B" />
        </svg>
        <div className="relative flex items-center gap-3">
          <img src={IMG(OWNER.photo)} alt={`Foto de ${OWNER.fullName}`} className="h-10 w-10 rounded-full bg-[#4A3A63] object-cover ring-2 ring-white/20" />
          <p className="text-[15px] text-white/80">Hola, {OWNER.name}. Así van tus cuentas.</p>
        </div>
        <p className="relative mt-6 text-sm text-white/70">Saldo total en {data.accounts.length} cuentas</p>
        <p className="cc-display cc-num relative mt-1 text-[44px] font-semibold leading-none sm:text-[52px]">{money(total)}</p>
        <div className="relative mt-7 grid grid-cols-3 gap-3 border-t border-white/15 pt-5">
          <Stat icon={<ArrowDownLeft size={16} />} tone="#7FD3B0" label="Ingresos" value={moneyRound(t.income)} />
          <Stat icon={<ArrowUpRight size={16} />} tone="#F4A394" label="Gastos" value={moneyRound(t.expense)} />
          <Stat icon={<PiggyBank size={16} />} tone="#F7C878" label={saved >= 0 ? 'Ahorro' : 'Déficit'} value={moneyRound(Math.abs(saved))} />
        </div>
      </section>

      {/* Cuentas */}
      <section className="grid grid-cols-2 gap-3 lg:col-span-5" aria-label="Cuentas">
        {data.accounts.map(a => {
          const b = balances[a.id] ?? 0;
          return (
            <div key={a.id} className="flex flex-col justify-between rounded-[22px] border border-[#E7E0EF] bg-white p-4 sm:p-5">
              <div className="flex items-center gap-2">
                <span className="h-2.5 w-2.5 shrink-0 rounded-full" style={{ background: a.color }} />
                <p className="truncate text-[14px] font-semibold text-[#2A1E3F]">{a.name}</p>
              </div>
              <div className="mt-4">
                <p className={clsx('cc-display cc-num text-[22px] font-semibold leading-tight sm:text-[24px]', b < 0 ? 'text-[#A8352D]' : 'text-[#2A1E3F]')}>{money(b)}</p>
                <p className="mt-0.5 truncate text-[13px] text-[#6B6178]">{b < 0 && a.id === 'tarjeta' ? 'Pendiente de cargo' : a.detail}</p>
              </div>
            </div>
          );
        })}
      </section>

      {/* Gasto por categoría */}
      <Card className="p-5 sm:p-6 lg:col-span-6">
        <CardTitle title="En qué se va el dinero" hint={`Gastos de ${monthLabel(month).toLowerCase()}`} />
        {t.expense === 0 ? (
          <p className="py-10 text-center text-[15px] text-[#6B6178]">Aún no hay gastos este mes. Cuando añadas uno, verás aquí el reparto.</p>
        ) : (
          <div className="flex flex-col items-center gap-5 sm:flex-row sm:items-center">
            <Donut slices={slices} total={t.expense} active={activeSlice} onActive={setActiveSlice} size={152} />
            <ul className="w-full min-w-0 flex-1 space-y-1">
              {slices.map(s => (
                <li key={s.id}>
                  <div
                    onMouseEnter={() => setActiveSlice(s.id)} onMouseLeave={() => setActiveSlice(null)}
                    className={clsx('flex items-center gap-2 rounded-xl px-2 py-1.5 text-[14px] transition-colors', activeSlice === s.id && 'bg-[#F6F1FB]')}
                  >
                    <span className="h-2.5 w-2.5 shrink-0 rounded-[4px]" style={{ background: s.color }} />
                    <span className="min-w-0 flex-1 truncate text-[#3E3352]">{s.label}</span>
                    <span className="cc-num shrink-0 text-[13px] text-[#6B6178]">{pct(s.value / t.expense)}</span>
                    <span className="cc-num w-[58px] shrink-0 text-right font-semibold text-[#2A1E3F]">{moneyRound(s.value)}</span>
                  </div>
                </li>
              ))}
            </ul>
          </div>
        )}
      </Card>

      {/* Evolución */}
      <Card className="p-5 sm:p-6 lg:col-span-6">
        <CardTitle
          title="Ingresos y gastos"
          hint="Últimos 6 meses · toca un mes"
          action={
            <div className="flex shrink-0 gap-3 pt-1 text-[13px] text-[#5E5470]">
              <span className="flex items-center gap-1.5"><span className="h-2.5 w-2.5 rounded-[3px] bg-[#2F8466]" />Ingresos</span>
              <span className="flex items-center gap-1.5"><span className="h-2.5 w-2.5 rounded-[3px] bg-[#E0705F]" />Gastos</span>
            </div>
          }
        />
        <MonthlyBars data={bars} selected={month} onSelect={setMonth} />
      </Card>

      {/* Presupuestos */}
      <Card className="p-5 sm:p-6 lg:col-span-5">
        <CardTitle
          title="Presupuestos del mes"
          hint={overCount ? `${overCount} ${overCount === 1 ? 'categoría se ha pasado' : 'categorías se han pasado'}` : 'Todo dentro de lo previsto'}
          action={<LinkBtn onClick={() => go('presupuestos')}>Ver todos</LinkBtn>}
        />
        <ul className="space-y-4">
          {budgets.map(b => {
            const c = catById(b.id);
            const over = b.spent > b.limit;
            return (
              <li key={b.id}>
                <div className="mb-1.5 flex items-center justify-between gap-2 text-[14px]">
                  <span className="flex min-w-0 items-center gap-1.5 font-semibold text-[#2A1E3F]">
                    {over && <AlertTriangle size={15} className="shrink-0 text-[#C2453C]" aria-label="Te has pasado" />}
                    <span className="truncate">{c.name}</span>
                  </span>
                  <span className="cc-num shrink-0 text-[#6B6178]">
                    <span className={clsx('font-semibold', over ? 'text-[#A8352D]' : 'text-[#2A1E3F]')}>{moneyRound(b.spent)}</span> de {moneyRound(b.limit)}
                  </span>
                </div>
                <Progress value={b.spent / b.limit} color={c.color} over={over} />
              </li>
            );
          })}
        </ul>
      </Card>

      {/* Últimos movimientos */}
      <Card className="p-3 pt-5 sm:p-4 sm:pt-6 lg:col-span-7">
        <div className="px-2 sm:px-2">
          <CardTitle title="Últimos movimientos" action={<LinkBtn onClick={() => go('movimientos')}>Ver todos los movimientos</LinkBtn>} />
        </div>
        <ul className="-mt-1">
          {recent.map(tx => <TxRow key={tx.id} tx={tx} account={accName(tx.accountId)} onOpen={onOpen} showDate />)}
        </ul>
      </Card>
    </div>
  );
}

function Stat({ icon, label, value, tone }: { icon: React.ReactNode; label: string; value: string; tone: string }) {
  return (
    <div className="min-w-0">
      <p className="flex items-center gap-1.5 text-[13px] text-white/70">
        <span style={{ color: tone }}>{icon}</span><span className="truncate">{label}</span>
      </p>
      <p className="cc-num mt-1 truncate text-[17px] font-semibold sm:text-[19px]">{value}</p>
    </div>
  );
}

function LinkBtn({ onClick, children }: { onClick: () => void; children: React.ReactNode }) {
  return (
    <button onClick={onClick} className="flex shrink-0 items-center gap-0.5 rounded-full px-2 py-1 text-[14px] font-semibold text-[#6A4FB0] hover:bg-[#F3EEF9]">
      {children}<ChevronRight size={16} />
    </button>
  );
}

import { useMemo, useState } from 'react';
import { clsx } from 'clsx';
import { Download, Plus, Search, SearchX, X } from 'lucide-react';
import { CATEGORIES, catById } from '../data/categories';
import type { Tx } from '../data/seed';
import { exportCSV } from '../lib/csv';
import { dayLabel, monthKey, monthLabel, signed, money } from '../lib/format';
import type { Finance } from '../lib/store';
import { TxRow } from './TxRow';
import { Button, Card } from './ui';

type TypeFilter = 'todos' | 'gasto' | 'ingreso';
type Props = { fin: Finance; month: string; onOpen: (tx: Tx) => void; onNew: () => void; notify: (t: string) => void };

export default function Transactions({ fin, month, onOpen, onNew, notify }: Props) {
  const { data } = fin;
  const [q, setQ] = useState('');
  const [type, setType] = useState<TypeFilter>('todos');
  const [cat, setCat] = useState('todas');
  const [acc, setAcc] = useState('todas');
  const [allMonths, setAllMonths] = useState(false);

  const list = useMemo(() => {
    const s = q.trim().toLowerCase();
    return data.txs.filter(t =>
      (allMonths || monthKey(t.date) === month) &&
      (type === 'todos' || t.type === type) &&
      (cat === 'todas' || t.categoryId === cat) &&
      (acc === 'todas' || t.accountId === acc) &&
      (!s || t.concept.toLowerCase().includes(s) || (t.note ?? '').toLowerCase().includes(s) || catById(t.categoryId).name.toLowerCase().includes(s)));
  }, [data.txs, q, type, cat, acc, allMonths, month]);

  const income = list.filter(t => t.type === 'ingreso').reduce((s, t) => s + t.amount, 0);
  const expense = list.filter(t => t.type === 'gasto').reduce((s, t) => s + t.amount, 0);
  const groups = useMemo(() => {
    const m = new Map<string, Tx[]>();
    for (const t of list) m.set(t.date, [...(m.get(t.date) ?? []), t]);
    return [...m.entries()];
  }, [list]);

  const filtered = q || type !== 'todos' || cat !== 'todas' || acc !== 'todas';
  const clear = () => { setQ(''); setType('todos'); setCat('todas'); setAcc('todas'); };
  const accName = (id: string) => data.accounts.find(a => a.id === id)?.name ?? '';
  const doExport = () => {
    exportCSV(list, data.accounts, `cuentas-claras-${allMonths ? 'historial' : month}.csv`);
    notify(`Exportados ${list.length} movimientos a CSV`);
  };

  return (
    <div className="space-y-5">
      <Card className="p-4 sm:p-5">
        <div className="flex flex-col gap-3 lg:flex-row lg:items-center">
          <label className="relative block flex-1">
            <span className="sr-only">Buscar movimientos</span>
            <Search size={18} className="pointer-events-none absolute left-3.5 top-1/2 -translate-y-1/2 text-[#8A7F98]" />
            <input className="cc-input !pl-10" placeholder="Buscar movimientos" value={q} onChange={e => setQ(e.target.value)} />
            {q && <button onClick={() => setQ('')} className="absolute right-2 top-1/2 grid h-8 w-8 -translate-y-1/2 place-items-center rounded-full text-[#6B6178] hover:bg-[#F1ECF7]" aria-label="Borrar búsqueda"><X size={16} /></button>}
          </label>
          <div className="inline-flex h-11 shrink-0 rounded-full bg-[#EDE6F5] p-1" role="tablist" aria-label="Tipo">
            {(['todos', 'gasto', 'ingreso'] as TypeFilter[]).map(k => (
              <button key={k} role="tab" aria-selected={type === k} onClick={() => setType(k)}
                className={clsx('flex-1 rounded-full px-4 text-[14px] font-semibold transition-colors', type === k ? 'bg-white text-[#2A1E3F] shadow-sm' : 'text-[#5E5470]')}>
                {k === 'todos' ? 'Todos' : k === 'gasto' ? 'Gastos' : 'Ingresos'}
              </button>
            ))}
          </div>
        </div>
        <div className="mt-3 grid grid-cols-2 gap-3 sm:flex sm:flex-wrap sm:items-center">
          <select className="cc-input sm:!w-52" value={cat} onChange={e => setCat(e.target.value)} aria-label="Categoría">
            <option value="todas">Categorías</option>
            {CATEGORIES.map(c => <option key={c.id} value={c.id}>{c.name}</option>)}
          </select>
          <select className="cc-input sm:!w-48" value={acc} onChange={e => setAcc(e.target.value)} aria-label="Cuenta">
            <option value="todas">Cuentas</option>
            {data.accounts.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}
          </select>
          <label className="flex h-11 cursor-pointer items-center gap-2.5 rounded-full px-1 text-[14px] font-medium text-[#3E3352]">
            <input type="checkbox" checked={allMonths} onChange={e => setAllMonths(e.target.checked)} className="h-[18px] w-[18px] accent-[#2A1E3F]" />
            Todos los meses
          </label>
          <div className="flex justify-end gap-2 sm:ml-auto">
            {filtered && <Button variant="ghost" size="sm" className="hidden sm:inline-flex" onClick={clear}>Quitar filtros</Button>}
            <Button variant="soft" size="sm" onClick={doExport} disabled={!list.length}><Download size={16} />Exportar CSV</Button>
          </div>
        </div>
      </Card>

      <div className="grid grid-cols-3 gap-3">
        <Figure label={allMonths ? 'Historial' : monthLabel(month, false)} value={`${list.length} mov.`} />
        <Figure label="Ingresos" value={money(income)} tone="text-[#24694F]" />
        <Figure label="Gastos" value={money(expense)} tone="text-[#A8352D]" />
      </div>

      {groups.length === 0 ? (
        <Card className="flex flex-col items-center px-6 py-14 text-center">
          <span className="grid h-14 w-14 place-items-center rounded-2xl bg-[#FFF4E2] text-[#B5761A]"><SearchX size={26} /></span>
          <p className="cc-display mt-4 text-[20px] font-semibold">No hay movimientos que mostrar</p>
          <p className="mt-1 max-w-sm text-[15px] text-[#6B6178]">
            {filtered ? 'Prueba con otra búsqueda o quita los filtros.' : `No has apuntado nada en ${monthLabel(month).toLowerCase()} todavía.`}
          </p>
          <div className="mt-5 flex gap-2">
            {filtered && <Button variant="soft" onClick={clear}>Quitar filtros</Button>}
            <Button onClick={onNew}><Plus size={17} />Añadir movimiento</Button>
          </div>
        </Card>
      ) : (
        <Card className="p-2 sm:p-3">
          {groups.map(([date, txs]) => {
            const net = txs.reduce((s, t) => s + (t.type === 'ingreso' ? t.amount : -t.amount), 0);
            return (
              <section key={date} className="border-b border-[#F0EBF5] py-2 last:border-0">
                <div className="flex items-baseline justify-between px-3 pb-1 pt-2">
                  <h3 className="text-[13px] font-semibold text-[#6B6178]">{dayLabel(date)}</h3>
                  <span className={clsx('cc-num text-[13px] font-semibold', net >= 0 ? 'text-[#24694F]' : 'text-[#6B6178]')}>{signed(net)}</span>
                </div>
                <ul>{txs.map(t => <TxRow key={t.id} tx={t} account={accName(t.accountId)} onOpen={onOpen} />)}</ul>
              </section>
            );
          })}
        </Card>
      )}
    </div>
  );
}

function Figure({ label, value, tone = 'text-[#2A1E3F]' }: { label: string; value: string; tone?: string }) {
  return (
    <div className="min-w-0 rounded-[20px] border border-[#E7E0EF] bg-white px-4 py-3.5">
      <p className="truncate text-[13px] text-[#6B6178]">{label}</p>
      <p className={clsx('cc-display cc-num mt-0.5 truncate text-[17px] font-semibold sm:text-[22px]', tone)}>{value}</p>
    </div>
  );
}

import { useState } from 'react';
import type { FormEvent } from 'react';
import { clsx } from 'clsx';
import { Trash2 } from 'lucide-react';
import { categoriesOf } from '../data/categories';
import type { Kind } from '../data/categories';
import type { Account, Tx } from '../data/seed';
import { currentMonth, parseAmount, todayISO } from '../lib/format';
import { Button, CatIcon, Modal } from './ui';

type Draft = Omit<Tx, 'id'> & { id?: string };
type Props = {
  tx: Tx | null; accounts: Account[]; defaultMonth: string;
  onClose: () => void; onSave: (tx: Draft) => void; onDelete: (tx: Tx) => void;
};
type Errors = Partial<Record<'amount' | 'concept' | 'date', string>>;

export default function TxForm({ tx, accounts, defaultMonth, onClose, onSave, onDelete }: Props) {
  const firstDate = defaultMonth === currentMonth() ? todayISO() : `${defaultMonth}-01`;
  const [type, setType] = useState<Kind>(tx?.type ?? 'gasto');
  const [amount, setAmount] = useState(tx ? tx.amount.toFixed(2).replace('.', ',') : '');
  const [concept, setConcept] = useState(tx?.concept ?? '');
  const [categoryId, setCategoryId] = useState(tx?.categoryId ?? 'super');
  const [accountId, setAccountId] = useState(tx?.accountId ?? 'corriente');
  const [date, setDate] = useState(tx?.date ?? firstDate);
  const [note, setNote] = useState(tx?.note ?? '');
  const [errors, setErrors] = useState<Errors>({});
  const [askDelete, setAskDelete] = useState(false);

  const cats = categoriesOf(type);
  const switchType = (k: Kind) => {
    setType(k);
    if (!categoriesOf(k).some(c => c.id === categoryId)) setCategoryId(categoriesOf(k)[0].id);
  };

  const submit = (e?: FormEvent) => {
    e?.preventDefault();
    const n = parseAmount(amount);
    const errs: Errors = {};
    if (!amount.trim()) errs.amount = 'Escribe el importe.';
    else if (!Number.isFinite(n) || n <= 0) errs.amount = 'El importe debe ser un número mayor que 0.';
    else if (n > 1_000_000) errs.amount = 'Ese importe parece demasiado alto.';
    if (concept.trim().length < 2) errs.concept = 'Pon un concepto para reconocerlo después (p. ej. «Mercadona»).';
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) errs.date = 'Elige una fecha.';
    else if (date > todayISO()) errs.date = 'La fecha no puede ser futura.';
    setErrors(errs);
    if (Object.keys(errs).length) return;
    onSave({
      id: tx?.id, type, amount: Math.round(n * 100) / 100, concept: concept.trim(), categoryId, accountId, date,
      note: note.trim() || undefined,
    });
  };

  const footer = askDelete && tx ? (
    <>
      <p className="mr-auto text-[14px] font-medium text-[#A8352D]">¿Borrar este movimiento?</p>
      <Button variant="ghost" onClick={() => setAskDelete(false)}>No</Button>
      <Button variant="danger" onClick={() => onDelete(tx)}>Sí, borrar</Button>
    </>
  ) : (
    <>
      {tx && <Button variant="danger" size="md" onClick={() => setAskDelete(true)} aria-label="Borrar movimiento"><Trash2 size={17} /><span className="hidden sm:inline">Borrar</span></Button>}
      <Button variant="ghost" className="ml-auto" onClick={onClose}>Cancelar</Button>
      <Button onClick={() => submit()}>{tx ? 'Guardar cambios' : type === 'gasto' ? 'Guardar gasto' : 'Guardar ingreso'}</Button>
    </>
  );

  return (
    <Modal title={tx ? 'Editar movimiento' : 'Nuevo movimiento'} onClose={onClose} footer={footer}>
      <form onSubmit={submit} noValidate className="space-y-5">
        <div className="grid grid-cols-2 rounded-full bg-[#EDE6F5] p-1" role="radiogroup" aria-label="Tipo de movimiento">
          {(['gasto', 'ingreso'] as Kind[]).map(k => (
            <button
              key={k} type="button" role="radio" aria-checked={type === k} onClick={() => switchType(k)}
              className={clsx('h-10 rounded-full text-[15px] font-semibold transition-colors',
                type === k ? (k === 'gasto' ? 'bg-white text-[#A8352D] shadow-sm' : 'bg-white text-[#24694F] shadow-sm') : 'text-[#5E5470]')}
            >
              {k === 'gasto' ? 'Gasto' : 'Ingreso'}
            </button>
          ))}
        </div>

        <Field label="Importe" error={errors.amount} htmlFor="tx-amount">
          <div className="relative">
            <input
              id="tx-amount" inputMode="decimal" autoComplete="off" placeholder="0,00" value={amount}
              onChange={e => setAmount(e.target.value)} aria-invalid={!!errors.amount}
              className="cc-input cc-display cc-num !h-14 pr-10 !text-[26px] font-semibold"
            />
            <span className="pointer-events-none absolute right-4 top-1/2 -translate-y-1/2 text-[20px] font-semibold text-[#8A7F98]">€</span>
          </div>
        </Field>

        <Field label="Concepto" error={errors.concept} htmlFor="tx-concept">
          <input id="tx-concept" className="cc-input" placeholder={type === 'gasto' ? 'Ej.: Compra en Mercadona' : 'Ej.: Nómina de octubre'}
            value={concept} onChange={e => setConcept(e.target.value)} aria-invalid={!!errors.concept} maxLength={60} />
        </Field>

        <fieldset>
          <legend className="mb-2 text-[14px] font-semibold text-[#3E3352]">Categoría</legend>
          <div className="grid grid-cols-2 gap-2 sm:grid-cols-3">
            {cats.map(c => (
              <button
                key={c.id} type="button" onClick={() => setCategoryId(c.id)} aria-pressed={categoryId === c.id}
                className={clsx('flex items-center gap-2 rounded-2xl border p-2 text-left text-[13px] font-semibold transition-colors',
                  categoryId === c.id ? 'border-[#2A1E3F] bg-white text-[#2A1E3F] ring-1 ring-[#2A1E3F]' : 'border-[#E2DAEC] bg-white/60 text-[#5E5470] hover:border-[#C9BDD8]')}
              >
                <CatIcon id={c.id} size={30} /><span className="min-w-0 leading-tight">{c.name}</span>
              </button>
            ))}
          </div>
        </fieldset>

        <div className="grid gap-4 sm:grid-cols-2">
          <Field label="Cuenta" htmlFor="tx-account">
            <select id="tx-account" className="cc-input" value={accountId} onChange={e => setAccountId(e.target.value)}>
              {accounts.map(a => <option key={a.id} value={a.id}>{a.name}</option>)}
            </select>
          </Field>
          <Field label="Fecha" error={errors.date} htmlFor="tx-date">
            <input id="tx-date" type="date" className="cc-input" value={date} max={todayISO()} onChange={e => setDate(e.target.value)} aria-invalid={!!errors.date} />
          </Field>
        </div>

        <Field label="Nota (opcional)" htmlFor="tx-note">
          <input id="tx-note" className="cc-input" placeholder="Algo que quieras recordar" value={note} onChange={e => setNote(e.target.value)} maxLength={120} />
        </Field>
        <button type="submit" className="hidden" aria-hidden="true" tabIndex={-1} />
      </form>
    </Modal>
  );
}

function Field({ label, error, htmlFor, children }: { label: string; error?: string; htmlFor: string; children: React.ReactNode }) {
  return (
    <div>
      <label htmlFor={htmlFor} className="mb-1.5 block text-[14px] font-semibold text-[#3E3352]">{label}</label>
      {children}
      {error && <p className="mt-1.5 text-[13px] font-medium text-[#A8352D]" role="alert">{error}</p>}
    </div>
  );
}

import { clsx } from 'clsx';
import { catById } from '../data/categories';
import type { Tx } from '../data/seed';
import { money, shortDate } from '../lib/format';
import { CatIcon } from './ui';

export function TxRow({ tx, account, onOpen, showDate }: { tx: Tx; account: string; onOpen: (tx: Tx) => void; showDate?: boolean }) {
  const cat = catById(tx.categoryId);
  const income = tx.type === 'ingreso';
  return (
    <li>
      <button
        onClick={() => onOpen(tx)}
        className="flex w-full items-center gap-3.5 rounded-2xl px-3 py-2.5 text-left transition-colors hover:bg-[#F7F3FA]"
        aria-label={`Editar ${tx.concept}`}
      >
        <CatIcon id={tx.categoryId} />
        <span className="min-w-0 flex-1">
          <span className="block truncate text-[15px] font-semibold text-[#2A1E3F]">{tx.concept}</span>
          <span className="block truncate text-[13px] text-[#6B6178]">
            {cat.name} · {account}{showDate ? ` · ${shortDate(tx.date)}` : ''}
          </span>
        </span>
        <span className={clsx('cc-num shrink-0 text-[15px] font-semibold', income ? 'text-[#2F8466]' : 'text-[#2A1E3F]')}>
          {income ? '+' : '−'}{money(tx.amount)}
        </span>
      </button>
    </li>
  );
}

import { useState } from 'react';
import type { CSSProperties } from 'react';
import { clsx } from 'clsx';
import { money, moneyRound, pct } from '../lib/format';

export type Slice = { id: string; label: string; value: number; color: string };

/** Dona de gasto por categoría. El hueco central muestra el total o la porción activa. */
export function Donut({ slices, total, active, onActive, size = 200 }: {
  slices: Slice[]; total: number; active: string | null; onActive: (id: string | null) => void; size?: number;
}) {
  const R = 76, C = 2 * Math.PI * R, GAP = slices.length > 1 ? 3 : 0;
  let acc = 0;
  const cur = slices.find(s => s.id === active);
  return (
    <div className="relative shrink-0" style={{ width: size, height: size }}>
      <svg viewBox="0 0 200 200" width={size} height={size} className="-rotate-90" role="img" aria-label="Gasto por categoría">
        <circle cx="100" cy="100" r={R} fill="none" stroke="#F1ECF6" strokeWidth="24" />
        {total > 0 && slices.map(s => {
          const len = (s.value / total) * C;
          const el = (
            <circle
              key={s.id} cx="100" cy="100" r={R} fill="none" stroke={s.color}
              strokeWidth={active === s.id ? 30 : 24}
              strokeDasharray={`${Math.max(0, len - GAP)} ${C}`} strokeDashoffset={-acc}
              className="cursor-pointer transition-[stroke-width,opacity] duration-200"
              style={{ opacity: active && active !== s.id ? 0.35 : 1 }}
              onMouseEnter={() => onActive(s.id)} onMouseLeave={() => onActive(null)}
            />
          );
          acc += len;
          return el;
        })}
        <circle cx="100" cy="100" r={R} fill="none" stroke="#FFFFFF" strokeWidth="32" strokeDasharray={`${C} ${C}`}
          className="cc-sweep pointer-events-none" style={{ ['--len' as string]: '0', strokeDashoffset: C } as CSSProperties} />
      </svg>
      <div className="pointer-events-none absolute inset-0 grid place-items-center text-center">
        <div className="px-6">
          <p className="text-[13px] leading-tight text-[#6B6178]">{cur ? cur.label : 'Gastado'}</p>
          <p className="cc-display cc-num mt-1 text-[24px] font-semibold leading-none text-[#2A1E3F]">{moneyRound(cur ? cur.value : total)}</p>
          {cur && <p className="mt-1 text-[13px] font-medium text-[#6B6178]">{pct(cur.value / total)} del mes</p>}
        </div>
      </div>
    </div>
  );
}

export type MonthBar = { key: string; label: string; income: number; expense: number };

const niceMax = (v: number) => {
  const step = v > 4000 ? 1000 : v > 2000 ? 500 : 250;
  return Math.max(step, Math.ceil(v / step) * step);
};

/** Barras agrupadas ingresos/gastos de los últimos meses. Clic en un mes para seleccionarlo. */
export function MonthlyBars({ data, selected, onSelect }: { data: MonthBar[]; selected: string; onSelect: (key: string) => void }) {
  const [hover, setHover] = useState<string | null>(null);
  const max = niceMax(Math.max(...data.map(d => Math.max(d.income, d.expense)), 1));
  const ticks = [max, max / 2, 0];
  const H = 168;
  return (
    <div className="relative flex gap-3" style={{ height: H + 28 }}>
      <div className="cc-num flex w-12 shrink-0 flex-col justify-between pb-7 text-right text-[12px] text-[#7A7088]" style={{ height: H + 28 }}>
        {ticks.map(t => <span key={t} className="-translate-y-2 leading-none">{t >= 1000 ? `${(t / 1000).toLocaleString('es-ES')} mil` : `${t} €`}</span>)}
      </div>
      <div className="relative flex-1">
        {ticks.map((t, i) => (
          <div key={t} className={clsx('absolute inset-x-0 border-t', i === 2 ? 'border-[#D9D0E4]' : 'border-dashed border-[#ECE6F2]')} style={{ top: (i * H) / 2 }} />
        ))}
        <div className="absolute inset-x-0 top-0 flex" style={{ height: H + 28 }}>
          {data.map(d => {
            const on = d.key === selected;
            const saved = d.income - d.expense;
            return (
              <button
                key={d.key}
                onClick={() => onSelect(d.key)}
                onMouseEnter={() => setHover(d.key)} onMouseLeave={() => setHover(null)} onFocus={() => setHover(d.key)} onBlur={() => setHover(null)}
                className={clsx('group relative flex flex-1 flex-col items-center rounded-xl transition-colors', on ? 'bg-[#F6F1FB]' : 'hover:bg-[#FAF7FC]')}
                aria-label={`${d.label}: ingresos ${money(d.income)}, gastos ${money(d.expense)}`}
              >
                <div className="flex w-full items-end justify-center gap-1.5 px-1" style={{ height: H }}>
                  <span className="cc-grow w-[38%] max-w-[18px] rounded-t-[6px] bg-[#2F8466]" style={{ height: (d.income / max) * H, opacity: on || hover === d.key ? 1 : 0.55 }} />
                  <span className="cc-grow w-[38%] max-w-[18px] rounded-t-[6px] bg-[#E0705F]" style={{ height: (d.expense / max) * H, opacity: on || hover === d.key ? 1 : 0.55 }} />
                </div>
                <span className={clsx('mt-2 text-[13px]', on ? 'font-bold text-[#2A1E3F]' : 'text-[#6B6178]')}>{d.label}</span>
                {hover === d.key && (
                  <span className="cc-fade pointer-events-none absolute bottom-[calc(100%-24px)] left-1/2 z-10 w-44 -translate-x-1/2 rounded-2xl bg-[#2A1E3F] p-3 text-left text-[13px] text-white shadow-lg">
                    <span className="mb-1 block font-semibold">{d.label}</span>
                    <span className="flex justify-between"><span className="text-white/70">Ingresos</span><span className="cc-num">{moneyRound(d.income)}</span></span>
                    <span className="flex justify-between"><span className="text-white/70">Gastos</span><span className="cc-num">{moneyRound(d.expense)}</span></span>
                    <span className="mt-1 flex justify-between border-t border-white/15 pt-1"><span className="text-white/70">{saved >= 0 ? 'Ahorro' : 'Déficit'}</span><span className="cc-num font-semibold text-[#F7C878]">{moneyRound(saved)}</span></span>
                  </span>
                )}
              </button>
            );
          })}
        </div>
      </div>
    </div>
  );
}

import { useEffect, useRef } from 'react';
import type { ButtonHTMLAttributes, ReactNode } from 'react';
