type BtnProps = ButtonHTMLAttributes<HTMLButtonElement> & { variant?: 'primary' | 'soft' | 'ghost' | 'danger'; size?: 'sm' | 'md' };

export function Button({ variant = 'primary', size = 'md', className, ...rest }: BtnProps) {
  return (
    <button
      {...rest}
      className={clsx(
        'inline-flex items-center justify-center gap-2 rounded-full font-semibold transition-colors disabled:opacity-50 disabled:cursor-not-allowed',
        size === 'md' ? 'h-11 px-5 text-[15px]' : 'h-9 px-3.5 text-sm',
        variant === 'primary' && 'bg-[#2A1E3F] text-white hover:bg-[#3D2C58]',
        variant === 'soft' && 'bg-[#EDE6F5] text-[#2A1E3F] hover:bg-[#E2D8EF]',
        variant === 'ghost' && 'text-[#5E5470] hover:bg-[#EDE6F5] hover:text-[#2A1E3F]',
        variant === 'danger' && 'bg-[#FBE9E7] text-[#A8352D] hover:bg-[#F7D9D5]',
        className,
      )}
    />
  );
}

export function Card({ className, children }: { className?: string; children: ReactNode }) {
  return <section className={clsx('rounded-[22px] border border-[#E7E0EF] bg-white', className)}>{children}</section>;
}

export function CardTitle({ title, hint, action }: { title: string; hint?: string; action?: ReactNode }) {
