}

export function CatIcon({ id, size = 40 }: { id: string; size?: number }) {
  const c = catById(id);
  const Icon = c.icon;
  return (
    <span className="grid shrink-0 place-items-center rounded-[14px]" style={{ width: size, height: size, background: `${c.color}1A`, color: c.color }}>
