export function Progress({ value, color, over }: { value: number; color: string; over?: boolean }) {
  return (
    <div className="h-2.5 overflow-hidden rounded-full bg-[#EFEAF4]" role="progressbar" aria-valuenow={Math.round(value * 100)} aria-valuemin={0} aria-valuemax={100}>
      <div className="cc-fill h-full rounded-full transition-[width] duration-500" style={{ width: `${Math.min(100, value * 100)}%`, background: over ? '#C2453C' : color }} />
    </div>
