}

export function MonthStepper({ month, onChange, className }: { month: string; onChange: (m: string) => void; className?: string }) {
  const isCurrent = month >= currentMonth();
  return (
    <div className={clsx('inline-flex h-11 items-center rounded-full border border-[#E2DAEC] bg-white p-1', className)}>
      <button className="grid h-9 w-9 place-items-center rounded-full text-[#2A1E3F] hover:bg-[#F1ECF7]" onClick={() => onChange(addMonths(month, -1))} aria-label="Mes anterior">
        <ChevronLeft size={18} />
      </button>
      <span className="min-w-[124px] text-center text-[15px] font-semibold text-[#2A1E3F]">{monthLabel(month)}</span>
      <button className="grid h-9 w-9 place-items-center rounded-full text-[#2A1E3F] hover:bg-[#F1ECF7] disabled:opacity-30 disabled:hover:bg-transparent" onClick={() => onChange(addMonths(month, 1))} disabled={isCurrent} aria-label="Mes siguiente">
        <ChevronRight size={18} />
      </button>
    </div>
  );
}

export function Modal({ title, onClose, children, footer }: { title: string; onClose: () => void; children: ReactNode; footer?: ReactNode }) {
  const ref = useRef<HTMLDivElement>(null);
  useEffect(() => {
    const onKey = (e: KeyboardEvent) => e.key === 'Escape' && onClose();
    window.addEventListener('keydown', onKey);
    (ref.current?.querySelector<HTMLElement>('input, select, textarea') ?? ref.current?.querySelector<HTMLElement>('button'))?.focus();
    return () => window.removeEventListener('keydown', onKey);
  }, [onClose]);
  return (
    <div className="cc-fade fixed inset-0 z-40 flex items-end justify-center bg-[#1B1329]/45 sm:items-center sm:p-6" onMouseDown={e => e.target === e.currentTarget && onClose()}>
      <div ref={ref} role="dialog" aria-modal="true" aria-label={title} className="cc-pop flex max-h-[92vh] w-full max-w-[520px] flex-col rounded-t-[26px] bg-[#FBFAFD] sm:rounded-[26px]">
        <div className="flex items-center justify-between px-6 pb-2 pt-5">
          <h2 className="cc-display text-[22px] font-semibold text-[#2A1E3F]">{title}</h2>
          <button onClick={onClose} className="grid h-9 w-9 place-items-center rounded-full text-[#5E5470] hover:bg-[#EDE6F5]" aria-label="Cerrar">
            <X size={20} />
          </button>
        </div>
        <div className="overflow-y-auto px-6 pb-4 pt-2">{children}</div>
        {footer && <div className="flex flex-wrap items-center gap-2 border-t border-[#ECE6F2] px-6 py-4">{footer}</div>}
      </div>
    </div>
  );
}

export type ToastMsg = { id: number; text: string; action?: { label: string; run: () => void } };

export function Toast({ toast, onDone }: { toast: ToastMsg | null; onDone: () => void }) {
  useEffect(() => {
    if (!toast) return;
    const t = setTimeout(onDone, 4500);
    return () => clearTimeout(t);
  }, [toast, onDone]);
  if (!toast) return null;
  return (
    <div className="pointer-events-none fixed inset-x-0 bottom-16 z-50 max-sm:bottom-16 flex justify-center px-4 sm:bottom-6">
      <div key={toast.id} role="status" className="cc-pop pointer-events-auto flex items-center gap-4 rounded-full bg-[#2A1E3F] py-2.5 pl-5 pr-2.5 text-sm text-white shadow-lg">
        <span>{toast.text}</span>
        {toast.action ? (
          <button className="rounded-full bg-[#F2A93B] px-3.5 py-1.5 font-semibold text-[#2A1E3F]" onClick={() => { toast.action!.run(); onDone(); }}>
            {toast.action.label}
          </button>
        ) : <span className="w-2" />}
      </div>
    </div>
  );
}

