import type { Kind } from './categories';
import { toISO } from '../lib/format';

export type Account = { id: string; name: string; detail: string; initial: number; color: string };
export type Tx = {
  id: string; date: string; amount: number; type: Kind;
  categoryId: string; accountId: string; concept: string; note?: string;
};
export type Data = { accounts: Account[]; txs: Tx[]; budgets: Record<string, number> };

export const OWNER = { name: 'Lucía', fullName: 'Lucía Herrera', photo: 'persona-1' };

export const ACCOUNTS: Account[] = [
  { id: 'corriente', name: 'Cuenta corriente', detail: 'Nómina y recibos', initial: 1240, color: '#2A1E3F' },
  { id: 'ahorro', name: 'Ahorros', detail: 'Colchón remunerado al 2 %', initial: 8600, color: '#2F8466' },
  { id: 'tarjeta', name: 'Tarjeta de crédito', detail: 'Se liquida el día 1', initial: 0, color: '#8B6FCB' },
  { id: 'efectivo', name: 'Efectivo', detail: 'Cartera', initial: 140, color: '#E39B2D' },
];

export const BUDGETS: Record<string, number> = {
  super: 340, restaurantes: 160, transporte: 110, ocio: 120, suscripciones: 45, ropa: 100, suministros: 140,
};

function rng(seed: number) {
  let s = seed;
  return () => { s = (s * 16807) % 2147483647; return (s - 1) / 2147483646; };
}

export function seedData(today = new Date()): Data {
  const r = rng(20261);
  const txs: Tx[] = [];
  let n = 0;
  const between = (a: number, b: number) => Math.round((a + r() * (b - a)) * 100) / 100;
  const pick = <T,>(xs: T[]) => xs[Math.floor(r() * xs.length)];

  for (let m = 5; m >= 0; m--) {
    const first = new Date(today.getFullYear(), today.getMonth() - m, 1);
    const dim = new Date(first.getFullYear(), first.getMonth() + 1, 0).getDate();
    const last = m === 0 ? today.getDate() : dim;
    const scale = last / dim;
    const add = (day: number, type: Kind, categoryId: string, concept: string, amount: number, accountId = 'corriente') => {
      if (day > last) return;
      const d = new Date(first.getFullYear(), first.getMonth(), Math.min(day, dim));
      txs.push({ id: `s${++n}`, date: toISO(d), amount, type, categoryId, accountId, concept });
    };
    const rand = (count: number) => Math.max(0, Math.round(count * scale));
    const day = () => 1 + Math.floor(r() * last);
    // Tarjeta y efectivo solo se usan en el mes en curso (la tarjeta se liquida cada día 1)
    const card = m === 0 ? 'tarjeta' : 'corriente';
    const cash = m === 0 ? 'efectivo' : 'corriente';

    add(1, 'ingreso', 'nomina', 'Nómina · Estudio Lumen', 2480);
    add(1, 'gasto', 'vivienda', 'Alquiler piso Ruzafa', 850);
    add(2, 'ingreso', 'otros', 'Intereses cuenta remunerada', between(12, 15), 'ahorro');
    add(3, 'gasto', 'salud', 'Cuota gimnasio Altafit', 34.9);
    add(5, 'gasto', 'suscripciones', 'Netflix', 12.99, card);
    add(9, 'gasto', 'suscripciones', 'Spotify Premium', 10.99, card);
    add(15, 'gasto', 'suscripciones', 'iCloud 200 GB', 2.99, card);
    add(8, 'gasto', 'suministros', 'Recibo de la luz · Iberdrola', between(42, 74));
    add(12, 'gasto', 'suministros', 'Fibra y móvil · Digi', 30);
    if (m % 2 === 0) add(20, 'gasto', 'suministros', 'Agua · Global Omnium', between(19, 27));
    if (m % 2 === 1) add(18, 'ingreso', 'freelance', 'Ilustraciones · Editorial Bromera', pick([420, 480, 560, 650]));

    for (let i = rand(8); i > 0; i--)
      add(day(), 'gasto', 'super', pick(['Mercadona', 'Lidl', 'Consum', 'Carrefour Express', 'Mercado Central']), between(14, 78), i % 3 ? card : 'corriente');
    for (let i = rand(5); i > 0; i--)
      add(day(), 'gasto', 'restaurantes', pick(['Bar Ricardo', 'Café de las Horas', 'La Pepica', 'Goiko', 'Horchatería Daniel', 'Casa Montaña']), between(8, 46), i % 2 ? card : cash);
    for (let i = rand(2); i > 0; i--) add(day(), 'gasto', 'transporte', 'Recarga Metrovalencia', 20, cash);
    if (r() > 0.3) add(day(), 'gasto', 'transporte', 'Gasolina · Repsol', between(42, 61), card);
    if (r() > 0.4) add(day(), 'gasto', 'transporte', 'Cabify', between(8, 15), card);
    for (let i = rand(3); i > 0; i--)
      add(day(), 'gasto', 'ocio', pick(['Cines Lys', 'Librería París-Valencia', 'Entradas concierto · Loco Club', 'Museo IVAM', 'Escape room']), between(8, 34), card);
    if (r() > 0.45) add(day(), 'gasto', 'ropa', pick(['Zara', 'Decathlon', 'Humana Vintage', 'Uniqlo']), between(24, 72), card);
    if (r() > 0.6) add(day(), 'gasto', 'salud', 'Farmacia Ruzafa', between(6, 24), cash);
    if (m === 2) {
      add(10, 'gasto', 'viajes', 'Vuelo Valencia–Lisboa · Vueling', 138);
      add(11, 'gasto', 'viajes', 'Apartamento en Lisboa (3 noches)', 264);
    }
    if (m === 0) {
      add(Math.min(4, last), 'gasto', 'restaurantes', 'Cena cumpleaños de Marta', 96, card);
      add(Math.min(6, last), 'gasto', 'restaurantes', 'Menú del día · Casa Montaña', 13.5, cash);
    }
  }
  txs.sort((a, b) => (a.date < b.date ? 1 : a.date > b.date ? -1 : 0));
  return { accounts: ACCOUNTS, txs, budgets: { ...BUDGETS } };
}

