import type { Account, Tx } from '../data/seed';
import { catById } from '../data/categories';

const cell = (v: string) => (/[;"\n]/.test(v) ? `"${v.replace(/"/g, '""')}"` : v);

/** Descarga los movimientos como CSV compatible con Excel en español (separador ";" y coma decimal) */
export function exportCSV(txs: Tx[], accounts: Account[], filename: string) {
  const accName = (id: string) => accounts.find(a => a.id === id)?.name ?? id;
  const rows = [
    ['Fecha', 'Concepto', 'Categoría', 'Cuenta', 'Tipo', 'Importe (EUR)', 'Nota'],
    ...txs.map(t => [
      t.date, t.concept, catById(t.categoryId).name, accName(t.accountId),
      t.type === 'ingreso' ? 'Ingreso' : 'Gasto',
      (t.type === 'ingreso' ? t.amount : -t.amount).toFixed(2).replace('.', ','),
      t.note ?? '',
    ]),
  ];
  const csv = '﻿' + rows.map(r => r.map(cell).join(';')).join('\n');
  const url = URL.createObjectURL(new Blob([csv], { type: 'text/csv;charset=utf-8' }));
  const a = document.createElement('a');
  a.href = url;
  a.download = filename;
  document.body.appendChild(a);
  a.click();
  a.remove();
  setTimeout(() => URL.revokeObjectURL(url), 1000);
}

const eur = new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR', useGrouping: 'always' } as Intl.NumberFormatOptions);
const eur0 = new Intl.NumberFormat('es-ES', { style: 'currency', currency: 'EUR', maximumFractionDigits: 0, useGrouping: 'always' } as Intl.NumberFormatOptions);

export const money = (n: number) => eur.format(n);
export const moneyRound = (n: number) => eur0.format(Math.round(n));
export const signed = (n: number) => (n > 0 ? '+' : n < 0 ? '−' : '') + eur.format(Math.abs(n));
export const pct = (n: number) => `${Math.round(n * 100)} %`;

const pad = (n: number) => String(n).padStart(2, '0');
export const toISO = (d: Date) => `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}`;
export const todayISO = () => toISO(new Date());
export const fromISO = (iso: string) => {
  const [y, m, d] = iso.split('-').map(Number);
  return new Date(y, m - 1, d);
};

export const monthKey = (iso: string) => iso.slice(0, 7);
export const currentMonth = () => monthKey(todayISO());
export const addMonths = (key: string, n: number) => {
  const [y, m] = key.split('-').map(Number);
  const d = new Date(y, m - 1 + n, 1);
  return `${d.getFullYear()}-${pad(d.getMonth() + 1)}`;
};

const cap = (s: string) => s.charAt(0).toUpperCase() + s.slice(1);
export const monthLabel = (key: string, withYear = true) => {
  const [y, m] = key.split('-').map(Number);
  const name = new Date(y, m - 1, 1).toLocaleDateString('es-ES', { month: 'long' });
  return withYear ? `${cap(name)} ${y}` : cap(name);
};
export const monthShort = (key: string) => {
  const [y, m] = key.split('-').map(Number);
  return cap(new Date(y, m - 1, 1).toLocaleDateString('es-ES', { month: 'short' }).replace('.', ''));
};

export const dayLabel = (iso: string) => {
  const today = todayISO();
  const y = new Date(); y.setDate(y.getDate() - 1);
  if (iso === today) return 'Hoy';
  if (iso === toISO(y)) return 'Ayer';
  return cap(fromISO(iso).toLocaleDateString('es-ES', { weekday: 'long', day: 'numeric', month: 'long' }));
};
export const shortDate = (iso: string) =>
  fromISO(iso).toLocaleDateString('es-ES', { day: 'numeric', month: 'short' }).replace('.', '');

/** "12,50" o "12.50" → 12.5 */
export const parseAmount = (s: string) => {
  const clean = s.trim().replace(/\s|€/g, '').replace(/\.(?=\d{3}(\D|$))/g, '').replace(',', '.');
  return clean === '' ? NaN : Number(clean);
};

import { useCallback, useEffect, useMemo, useState } from 'react';
import { seedData } from '../data/seed';
import type { Data, Tx } from '../data/seed';
import { monthKey } from './format';

const KEY = 'cuentas-claras:v1';

function load(): Data {
  try {
    const raw = localStorage.getItem(KEY);
    if (raw) {
      const d = JSON.parse(raw) as Data;
      if (Array.isArray(d.txs) && Array.isArray(d.accounts)) return d;
    }
  } catch { /* datos dañados: empezamos de cero */ }
  return seedData();
}

const sortTxs = (txs: Tx[]) => [...txs].sort((a, b) => (a.date === b.date ? b.id.localeCompare(a.id) : a.date < b.date ? 1 : -1));

export function useFinance() {
  const [data, setData] = useState<Data>(load);

  useEffect(() => {
    try { localStorage.setItem(KEY, JSON.stringify(data)); } catch { /* sin almacenamiento */ }
  }, [data]);

  const addTx = useCallback((tx: Omit<Tx, 'id'>) => {
    setData(d => ({ ...d, txs: sortTxs([{ ...tx, id: `u${Date.now()}` }, ...d.txs]) }));
  }, []);
  const updateTx = useCallback((tx: Tx) => {
    setData(d => ({ ...d, txs: sortTxs(d.txs.map(t => (t.id === tx.id ? tx : t))) }));
  }, []);
  const deleteTx = useCallback((id: string) => {
    setData(d => ({ ...d, txs: d.txs.filter(t => t.id !== id) }));
  }, []);
  const restoreTx = useCallback((tx: Tx) => {
    setData(d => ({ ...d, txs: sortTxs([tx, ...d.txs.filter(t => t.id !== tx.id)]) }));
  }, []);
  const setBudget = useCallback((categoryId: string, limit: number | null) => {
    setData(d => {
      const budgets = { ...d.budgets };
      if (limit === null) delete budgets[categoryId]; else budgets[categoryId] = limit;
      return { ...d, budgets };
    });
  }, []);
  const reset = useCallback(() => setData(seedData()), []);

  const balances = useMemo(() => {
    const b: Record<string, number> = {};
    for (const a of data.accounts) b[a.id] = a.initial;
    for (const t of data.txs) b[t.accountId] = (b[t.accountId] ?? 0) + (t.type === 'ingreso' ? t.amount : -t.amount);
    return b;
  }, [data]);

  return { data, balances, addTx, updateTx, deleteTx, restoreTx, setBudget, reset };
}

export type Finance = ReturnType<typeof useFinance>;

/** Totales de un mes: ingresos, gastos y gasto por categoría */
export function monthTotals(txs: Tx[], month: string) {
  let income = 0, expense = 0;
  const byCat: Record<string, number> = {};
  for (const t of txs) {
    if (monthKey(t.date) !== month) continue;
    if (t.type === 'ingreso') income += t.amount;
    else { expense += t.amount; byCat[t.categoryId] = (byCat[t.categoryId] ?? 0) + t.amount; }
  }
  return { income, expense, byCat };
}
